  "Bahasa Indonesia|11": "Bahasa Indonesia",
  "Bahasa Indonesia|12": "Bahasa Indonesia",
  "Bahasa Inggris|10": "Bahasa Inggris",
  "Bahasa Inggris|11": "Bahasa Inggris",
  "Bahasa Inggris|12": "Bahasa Inggris",
  "Informatika|10": "Informatika",
  "Pendidikan Pancasila|10": "Pendidikan Pancasila",
